import{_ as a,o as i,c as n,a0 as o}from"./chunks/framework.DhQjJcnt.js";const u=JSON.parse('{"title":"Skill: /grill-api-spec","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/grill-api-spec.md","filePath":"references/skills/grill-api-spec.md"}'),c={name:"references/skills/grill-api-spec.md"};function t(l,e,r,s,d,p){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="skill-grill-api-spec" tabindex="-1">Skill: <code>/grill-api-spec</code> <a class="header-anchor" href="#skill-grill-api-spec" aria-label="Permalink to &quot;Skill: `/grill-api-spec`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>grill-api-spec</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/grill-api-spec &lt;page-id/slug&gt;</code></li><li>Luôn phải chạy sau <code>/api-spec</code> và trước khi qua bước bộ code (<code>/api</code>) của Backend.</li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Đọc <code>ir/design.yaml</code> để xác minh lại việc Frontend cần những API gì (actions / apiRefs).</li><li>Đọc file hợp đồng Backend vừa tạo <code>01-backend-spec.yaml</code>.</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>File <code>01-backend-spec.yaml</code> được vá/sửa đổi nếu phát hiện sai sót.</li><li>Bổ sung các thẻ gencode (<code>codegen.profile</code>, <code>entity</code>, <code>module</code>, <code>#gen:*</code>) vào <code>01-backend-spec.yaml</code>.</li><li>Chạy qua các cổng kiểm định CLI: <code>flowgrid openapi_gen</code> và <code>flowgrid openapi_render</code>.</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Kỹ năng <strong>kiểm toán (Audit)</strong> độc quyền cho Technical Backend.</li><li>Đối soát khắt khe giữa những gì thiết kế FE yêu cầu và những gì API cung cấp (Database schemas, API endpoints, data types, securitySchemes).</li><li><strong>Kiểm định thẻ <code>#reuse-api</code>:</strong> Quét lại toàn bộ các actions của Frontend xem có vi phạm việc đẻ ra các API dư thừa hay không. Nếu action nào có <code>#reuse-api</code> thì file YAML đó không được quyền đẻ ra <code>api/&lt;seq&gt;</code> mới.</li><li><strong>Kiểm định Error Matrix:</strong> Kiểm tra gắt gao các mã lỗi (Endpoint Error Storming Matrix). Ví dụ route có tham số <code>{id}</code> bắt buộc phải cover lỗi 404 và 403 IDOR. Form Submit phải cover lỗi 422.</li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li><strong>Trước đó:</strong> <code>/api-spec</code>.</li><li><strong>Sau đó:</strong> <code>pnpm docs:render</code> để team review giao diện, sau đó bàn giao cho bộ code BE (<code>/api</code>) để đẻ source code thực tế.</li></ul><h2 id="chu-y-quan-trong" tabindex="-1">Chú ý quan trọng <a class="header-anchor" href="#chu-y-quan-trong" aria-label="Permalink to &quot;Chú ý quan trọng&quot;">​</a></h2><ul><li><strong>Cấm đoán:</strong> Tuyệt đối không sinh Markdown reports, BQA 3-Pillars reports hay mã nguồn (FastAPI, Laravel) bằng tay.</li><li>Mọi Tech Debt (Câu hỏi chưa rõ ràng) đều phải được tracking dưới dạng <code>#tech-debt:QA-&lt;feature.id&gt;-NNNN</code> và đối chiếu bằng file vật lý trong <code>qa/open/</code>. Không được để lại <code>openQuestions</code>.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/grill-api-spec</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',20)])])}const g=a(c,[["render",t]]);export{u as __pageData,g as default};
